        {
          "option": "Keep DOT files authoritative and mirror into ActiveGraph permanently",
          "rejected": "Two writable sources of truth drift; replay and fork are meaningless when the mirror is not authoritative."
        },
        {
          "option": "Extend beads into the shared runtime state store",
          "rejected": "Beads is a tracker with git-sync semantics — no subscriptions, replay, fork, or scoped views."
        },
        {
          "option": "Build a bespoke event log inside execution_engine",
          "rejected": "Reinvents replay, fork, diff and approvals that activegraph 1.x already provides under a determinism contract."
        }
      ],
